"""The shapes the `family-graph` matrix needs, grown into the canonical fixture (plan T4.5).

The design wanted this as a `graph3` fixture built over raw REST on every run: 26 POSTs and
40–170 s per run, and a second tree in the repo that contradicts the first. Its two arguments
were that the `people-names` matrix pinned `families == 0` and that hand-written `<childref>`
cross-references are too error-prone to trust. Phase 1 retired both — the canonical fixture has
22 families, and it is *generated* through the server's own tools rather than hand-written.

So the shapes move in here. Each block below names the cases it exists for: a subject that
quietly disappears in a later rebuild should be a red test, not a silent no-op.

**Where this runs is load-bearing.** `build_fixture.build()` calls `grow()` last, after
`stage2_subjects.grow()`. Ids are server-assigned in creation order, so inserting it anywhere
earlier renumbers every Stage-2 subject and every id in `test_00_stage2_catalog.py`.

**No `article()` calls.** `Builder.grow` writes one blog post per family it created, and
`test_05_fixture.py` requires the year 1912 to appear in exactly one note.

**Names are chosen against `test_00_fixture_xml.py`'s invariant**, not for flavour: no name may
be a substring of any other, or `search_person` counts stop being deterministic. The design's own
cast would have broken it three times — `Anselma` inside the three `Anselm`s, a fourth `Bertram`,
a fifth `Cordula` — and its `Steinmoor` shares a prefix with `Steinbrecht` and `Steinfeld`. Those
four are renamed or dropped here. The remaining surnames were checked in both directions against
all seventeen fixture surnames, `Wendelmark`, and every given name.
"""

from __future__ import annotations

from fixtures.builder import FEMALE, MALE, UNKNOWN, Builder

OTHER = 3

LINEAGE_SURNAME = "Falkenrieder"
PARTNER_SURNAMES = ("Nebelhorn", "Wolkenstein")

# Eight people in no family at all, for the parent-slot cases (FG-16…FG-23), which need spouses
# they may marry off and displace. **New** people rather than the twelve loose ones the fixture
# already has: every one of those is a declared Stage-2 subject, and uc22 *mutates* the gender of
# five of them — a Stage-1 matrix built on them would borrow Stage-2's meaning, and a Stage-2
# sweep would rewrite a Stage-1 substrate. `birth_year=None` on purpose: they create no event,
# which keeps the cost of eight spare people to eight objects.
LOOSE = (
    ("Meinrada", "Zwiebelbach", FEMALE),
    ("Norbert", "Zwiebelbach", MALE),
    ("Oswalda", "Kranichfeld", FEMALE),
    ("Pankratius", "Kranichfeld", MALE),
    ("Quirina", "Nebelhorn", UNKNOWN),
    ("Roderich", "Nebelhorn", UNKNOWN),
    ("Sieglinde", "Ohnesorg", FEMALE),
    # The only gender 3 in the fixture (FG-21). Nothing in the product validates the range —
    # `server.py` takes an int and `gramps_client` never checks it — so this is also the one
    # record that would notice if a future version started to.
    ("Theobald", "Ohnesorg", OTHER),
)


def grow(builder: Builder) -> dict[str, str]:
    """Four generations in five families. Returns the roles the build has to measure.

    Roles rather than ids: which id each person gets is the server's business, and the caller
    needs to know *which person is the remarried one*, not that they are `I0061`.
    """
    founder = builder.person("Wendelin", LINEAGE_SURNAME, MALE, 1874)
    founder_wife = builder.person("Almuth", LINEAGE_SURNAME, FEMALE, 1876)
    # The remarried son, and his brother who will be a single parent.
    son = builder.person("Emmerich", LINEAGE_SURNAME, MALE, 1902)
    brother = builder.person("Gerwald", LINEAGE_SURNAME, MALE, 1904)
    # Gender 2 in the *mother* slot: `_assign_parent_handles` only moves a person to the mother
    # slot for gender 0, so a male-plus-unknown couple falls through to call order and the
    # Unknown one lands there. That is the shape `get_relations` must not relabel by gender.
    partner = builder.person("Fridolin", PARTNER_SURNAMES[0], UNKNOWN, 1903)
    # The adopted child: a member of two parent families, which is what makes `get_ancestors`
    # traverse more than one and report three parents rather than two.
    adopted = builder.person("Isentrud", LINEAGE_SURNAME, FEMALE, 1930)
    sibling = builder.person("Jorund", LINEAGE_SURNAME, MALE, 1932)
    second_wife = builder.person("Hiltrud", PARTNER_SURNAMES[1], FEMALE, 1905)
    half_sibling = builder.person("Kunibert", LINEAGE_SURNAME, MALE, 1935)
    # The fourth generation, and the only reason a `grade >= 3` ceiling case can terminate on a
    # real leaf instead of saturating one level down and proving nothing.
    great_grandchild = builder.person("Liutgard", LINEAGE_SURNAME, FEMALE, 1958)

    root = builder.family(founder, founder_wife, (son, brother))
    main = builder.family(son, partner, (adopted, sibling))
    # The second marriage. `get_descendants(son, 1)` has to merge the children of both.
    second = builder.family(son, second_wife, (half_sibling,))
    # Single parent with the **father** slot filled — the mirror of F0021, whose lone female
    # spouse lands in the mother slot. Both orientations exist so a case cannot pass by assuming
    # the empty slot is always the father's.
    adopting = builder.family(brother, children=(adopted,))
    leaf = builder.family(adopted, children=(great_grandchild,))

    for first_name, surname, gender in LOOSE:
        builder.person(first_name, surname, gender)

    return {
        "lineage_surname": LINEAGE_SURNAME,
        "founder": founder,
        "remarried": son,
        "adopted_child": adopted,
        "deepest": great_grandchild,
        "single_parent_family": adopting,
        "root_family": root,
        "main_family": main,
        "second_family": second,
        "leaf_family": leaf,
    }
